import heapq

def match(orders):
    trades = []
    book = {}  # id -> dict(side, price, remaining, active)
    buy_heap = []  # (-price, arrival, id)
    sell_heap = []  # (price, arrival, id)
    arrival_counter = 0

    def get_top(heap):
        while heap:
            item = heap[0]
            oid = item[2]
            o = book.get(oid)
            if o is None or not o['active']:
                heapq.heappop(heap)
                continue
            return item
        return None

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            o = book.get(oid)
            if o is not None and o['active']:
                o['active'] = False
            continue

        oid = order[1]
        side = order[2]
        if typ == 'market':
            qty = order[3]
            price = None
        else:
            price = order[3]
            qty = order[4]

        remaining = qty

        if side == 'buy':
            opp_heap = sell_heap
        else:
            opp_heap = buy_heap

        while remaining > 0:
            top = get_top(opp_heap)
            if top is None:
                break
            resting_id = top[2]
            resting = book[resting_id]
            resting_price = resting['price']

            if typ != 'market':
                if side == 'buy':
                    if resting_price > price:
                        break
                else:
                    if resting_price < price:
                        break

            trade_qty = min(remaining, resting['remaining'])
            if side == 'buy':
                buy_id = oid
                sell_id = resting_id
            else:
                buy_id = resting_id
                sell_id = oid

            trades.append([buy_id, sell_id, resting_price, trade_qty])

            remaining -= trade_qty
            resting['remaining'] -= trade_qty

            if resting['remaining'] == 0:
                resting['active'] = False
                heapq.heappop(opp_heap)

        if typ == 'limit' and remaining > 0:
            book[oid] = {
                'side': side,
                'price': price,
                'remaining': remaining,
                'active': True
            }
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, arrival_counter, oid))
            else:
                heapq.heappush(sell_heap, (price, arrival_counter, oid))

        arrival_counter += 1

    return trades

